# greet

A tiny CLI that greets someone.

    greet [--shout] <name>
use std::env;
use std::process::ExitCode;

fn usage() -> &'static str {
    "usage: greet [--shout] <name>"
}

fn main() -> ExitCode {
    let mut shout = false;
    let mut name = None;
    for arg in env::args().skip(1) {
        match arg.as_str() {
            "--shout" => shout = true,
            "-h" | "--help" => {
                println!("{}", usage());
                return ExitCode::SUCCESS;
            }
            other if other.starts_with('-') => {
                eprintln!("unknown flag: {other}\n{}", usage());
                return ExitCode::from(2);
            }
            other => name = Some(other.to_owned()),
        }
    }
    let Some(name) = name else {
        eprintln!("{}", usage());
        return ExitCode::from(2);
    };
    let line = greeting(&name);
    println!("{}", if shout { line.to_uppercase() } else { line });
    ExitCode::SUCCESS
}

fn greeting(name: &str) -> String {
    format!("Hello, {name}!")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn greets_by_name() {
        assert_eq!(greeting("Ada"), "Hello, Ada!");
    }
}

